import{_ as e,c as l,o as i,ag as t}from"./chunks/framework.B3RpK1bM.js";const u=JSON.parse('{"title":"定义","description":"","frontmatter":{},"headers":[],"relativePath":"zh_CN/definition.md","filePath":"zh_CN/definition.md","lastUpdated":1769658044000}'),n={name:"zh_CN/definition.md"};function o(r,a,d,s,h,_){return i(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h1><p><a href="./">返回目录</a></p><p>为保障开发者、用户能使用规范地描述供需关系，保障交流过程不会产生歧意，以下针对一些重要概念进行定义，一般情况下我们默认开发者、用户能够理解以下概念。</p><h2 id="逻辑定义" tabindex="-1">逻辑定义 <a class="header-anchor" href="#逻辑定义" aria-label="Permalink to &quot;逻辑定义&quot;">​</a></h2><ul><li>视觉小说游戏（NVL-Novel Visual Game）：以文字为描写为主，插入图片辅助表现为手段的一类游戏</li><li>文字冒险游戏（ADV-Text Adventure Game）：通过台本形式以文字交流为主，结合图像、音乐与演出进行交互的一类电子游戏。</li><li>美少女恋爱游戏、旮旯给木（galgame）：以动画美少女互动为核心的一类游戏题材。</li><li>低代码开发（Low code）：以少量、低成本的手写代码实现快速开发的一种开发模式。</li><li>游戏引擎：用于游戏开发的一套软件框架，在ezgal中将着重表示游戏开发过程中核心的依赖软件。</li></ul><h2 id="功能定义" tabindex="-1">功能定义 <a class="header-anchor" href="#功能定义" aria-label="Permalink to &quot;功能定义&quot;">​</a></h2><ul><li>全屏框（Full screen）：全屏框是便于视觉小说游戏（NVL）的文字描写窗口，占用屏幕主要空间。</li><li>对话框（dialogue）：对话框是便于文字冒险游戏（ADV）的对话窗口，一般占用文字底部，主要用于体现角色交流。</li></ul><h2 id="语言定义" tabindex="-1">语言定义 <a class="header-anchor" href="#语言定义" aria-label="Permalink to &quot;语言定义&quot;">​</a></h2><ul><li>ezlang：ezlang（轻语言）是ezgal的解释器，用于将开发者的台本式语言解释为json格式的定制语言，核心理念是实现低学习成本的脚本化低代码开发。</li><li>台本：台本包含剧本与演出两个部分，是ezlang的核心概念。</li><li>剧本：剧本是ezlang语言的核心概念之一，以类话剧文书的形式体现，主要包括文本、对话与选项。</li><li>演出：演出包括图片、声音、特效等相关元素的控制，是ezlang的补充功能。</li></ul>',9)])])}const f=e(n,[["render",o]]);export{u as __pageData,f as default};
